// REQUIRES: malterlib-plugin
// The coroutine and actor checks through the plugin on code that doesn't
// compile, coroutine-invalid-code.cpp's: no crash, the errors reported, nothing
// else; and coroutine-uncompilable.cpp's, whose reports go with its error.
// RUN: not %clang -fno-crash-diagnostics -fplugin-arg-malterlib-options-file=%S/Inputs/ClangTidyOptions.yaml -fsyntax-only -std=c++20 -I %S/Inputs '-fplugin-arg-malterlib-checks=-*,malterlib-actor-*,malterlib-coroutine-*,malterlib-async-destroy,malterlib-coawait-*,malterlib-continue-running-on-actor,malterlib-runs-to-completion,malterlib-thread-local-storage' %S/coroutine-invalid-code.cpp 2>&1 | FileCheck --implicit-check-not='Stack dump' --implicit-check-not='[malterlib-' --check-prefix=CHECK-ERRORS %S/coroutine-invalid-code.cpp
// RUN: not %clang -fno-crash-diagnostics -fplugin-arg-malterlib-options-file=%S/Inputs/ClangTidyOptions.yaml -fsyntax-only -std=c++20 -I %S/Inputs -DFATAL '-fplugin-arg-malterlib-checks=-*,malterlib-actor-*,malterlib-coroutine-*,malterlib-async-destroy,malterlib-coawait-*,malterlib-continue-running-on-actor,malterlib-runs-to-completion,malterlib-thread-local-storage' %S/coroutine-invalid-code.cpp 2>&1 | FileCheck --implicit-check-not='Stack dump' --implicit-check-not='[malterlib-' --check-prefix=CHECK-FATAL %S/coroutine-invalid-code.cpp
// RUN: not %clang -fno-crash-diagnostics -fplugin-arg-malterlib-options-file=%S/Inputs/ClangTidyOptions.yaml -fsyntax-only -std=c++20 -I %S/Inputs -DBROKEN '-fplugin-arg-malterlib-checks=-*,malterlib-actor-*,malterlib-coroutine-*,malterlib-async-destroy,malterlib-coawait-*,malterlib-continue-running-on-actor,malterlib-runs-to-completion,malterlib-thread-local-storage' %S/coroutine-uncompilable.cpp 2>&1 | FileCheck --implicit-check-not='Stack dump' --implicit-check-not='[malterlib-' --check-prefix=CHECK-BROKEN %S/coroutine-uncompilable.cpp
